mapper.sql:
SELECT sum(timestampdiff(MINUTE,b.begin_time,a.time)) AS `taskTime`
from inspect_record a
left join inspect_task b on a.task_id = b.id

    a.time is not null

        and a.create_time between #{param.period.begin} and #{param.period.end}


        and b.type_id = #{typeId};

mapper.select:
SELECT sum(FLOOR(EXTRACT(EPOCH FROM (a.time-b.begin_time))/60)) AS `taskTime`
from inspect_record a
left join inspect_task b on a.task_id = b.id

    a.time is not null

        and a.create_time between #{param.period.begin} and #{param.period.end}


        and b.type_id = #{typeId};

SELECT count(a.id) as inspectionNum,a.target_id as objId,a.target_name as objName from inspect_record a


        and a.time between #{param.period.begin} and #{param.period.end}


        and a.target_category = #{param.objType}

    group by a.target_id
    order by inspectionNum desc

SELECT count(a.id) from inspect_record_item a
left join inspect_record b on a.record_id = b.id

    a.error_value_flag = '1' and b.id is not null

        and b.time  >=  #{startTime}


        and b.time  <=  #{endTime}


        and b.target_id = #{objId}

SELECT count(a.id) as inspectionNum,b.target_id as objId,b.target_name as objName from inspect_record_item a
left join inspect_record b on a.record_id = b.id

    a.error_value_flag = '1' and b.id is not null

        and b.time between #{param.period.begin} and #{param.period.end}


        and b.target_category = #{param.objType}


group by b.target_id order by inspectionNum desc

SELECT count(a.id) as inspectionNum, b.target_id as objId,b.target_name as objName from inspect_task a left join inspect_record b on a.id = b.task_id where b.target_id is not null and b.target_name is not null
and b.target_category = #{param.objType}
and a.create_time between #{param.period.begin} and #{param.period.end}
GROUP BY b.target_id order by inspectionNum desc

SELECT id as recordId,target_id as targetId,target_name as targetName, result , nickname as username
from inspect_record

    `status` = 'OVER'

        and task_id = #{taskId}


ORDER BY result ASC;

SELECT target_category as name, count(1) as num
FROM `inspect_record` a
inner join inspect_task b on a.task_id = b.id
where begin_time >= #{param.period.begin}
and end_time <= #{param.period.end}
GROUP BY target_category

select a.organization_id as depId, count(a.id) as inspectionNum from inspect_record a
a.status = 'OVER'
and a.organization_id in
#{depId}
and a.time between #{period.begin} and #{period.end}
group by a.organization_id

select target_id as deviceId, count(id) as num, count(distinct task_id) as task_num, COALESCE(SUM(if(`result` = 'ABNORMAL',1,0)),0) as `abnormal_num` from inspect_record
target_category = 'DEVICE'
and target_id in
#{id}
and create_time between #{param.period.begin} and #{param.period.end}
group by target_id

select count(*) from ( select ir.target_id from inspect_record ir inner join inspect_record_item iri on (ir.id = iri.record_id) where ir.target_id in
#{targetId}
and iri.error_value_flag = 1 group by ir.target_id ) t

SELECT ir.id, ir.target_category, ir.target_id, ir.target_name, ir.STATUS, ir.repair_status, ir.`result`, ir.nickname, ir.task_name, ir.`time`, ir.remark, group_concat( iri.item_name ) AS item_name FROM inspect_record ir LEFT JOIN inspect_record_item iri ON ( ir.id = iri.record_id )
ir.plan_id = #{param.planId}
and ir.task_id = #{param.taskId}
and ir.task_id in
#{taskId}
and ir.target_category = #{param.targetCategory}
and ir.target_category = #{param.targetCategory}
and ir.target_name = #{param.keyword}
and ir.result = #{param.result}
and ir.status = #{param.status}
GROUP BY ir.target_id

SELECT ir.id, ir.target_category, ir.target_id, ir.target_name, ir.STATUS, ir.`result`, ir.nickname, ir.task_name, ir.`time`, ir.remark, LISTAGG(iri.item_name, ',') AS item_name FROM inspect_record ir LEFT JOIN inspect_record_item iri ON ( ir.id = iri.record_id )
ir.plan_id = #{param.planId}
and ir.task_id = #{param.taskId}
and ir.task_id in
#{taskId}
and ir.target_category = #{param.targetCategory}
and ir.target_name = #{param.keyword}
and ir.result = #{param.result}
and ir.status = #{param.status}
GROUP BY ir.target_id

SELECT ir.id, ir.target_category, ir.target_id, ir.target_name, ir.STATUS, ir.`result`, ir.nickname, ir.task_name, ir.`time`, ir.remark, STRING_AGG(iri.item_name, ',') AS item_name FROM inspect_record ir LEFT JOIN inspect_record_item iri ON ( ir.id = iri.record_id )
ir.plan_id = #{param.planId}
and ir.task_id = #{param.taskId}
and ir.task_id in
#{taskId}
and ir.target_category = #{param.targetCategory}
and ir.target_name = #{param.keyword}
and ir.result = #{param.result}
and ir.status = #{param.status}
GROUP BY ir.target_id

SELECT
COALESCE(ir.task_name, it.name) AS task_name,
ittr.target_name,
iri.item_name,
iri.item_result_name AS result,
ir.nickname,
COALESCE(iri.create_time, ir.`time`) AS time,
iri.error_desc AS remark
FROM inspect_task_target_relation ittr
LEFT JOIN inspect_task it ON it.id = ittr.task_id
LEFT JOIN inspect_record ir ON ir.task_id = ittr.task_id AND ir.target_id = ittr.target_id
LEFT JOIN inspect_record_item iri ON ir.id = iri.record_id

    ittr.plan_id = #{param.planId}

        AND ittr.task_id = #{param.taskId}


        AND ittr.task_id IN

            #{taskId}



        AND ittr.target_category = #{param.targetCategory}


        AND ittr.target_name = #{param.keyword}


        AND ir.result = #{param.result}




                AND (ir.id IS NULL OR ir.status = 'EXECUTING')


                AND ir.status = #{param.status}




ORDER BY ittr.id, ir.id, iri.id

select ir.`id`, ir.`target_name` ,ir.`task_name` , ir.`time` , ir.`nickname` ,ir.`result` from `inspect_record` ir inner join `inspect_record_item` iri on(iri.`record_id` = ir.`id`) where iri.`error_value_flag` = 1
and ir.`time` between #{param.period.begin} and #{param.period.end}
and ir.`target_name` like CONCAT('%',#{param.targetName},'%')
and iri.`item_tag` in
#{tag}
group by ir.`id`

SELECT ir.id, ir.target_category, ir.target_id, ir.target_name, if(ir.task_id is null , '临时巡检' , '任务巡检') as inspectMethod, ir.task_id, ir.task_name, ir.status, ir.organization_id, ir.organization_name, ir.user_id, ir.nickname, ir.`time`, ir.`result`, ir.cancel_reason, ir.cancel_file_key, group_concat(iri.item_name) as errNames, group_concat(iri.error_desc) as errDesc FROM inspect_record ir LEFT JOIN inspect_record_item iri ON ( iri.record_id = ir.id and iri.error_value_flag = 1) WHERE ir.`result` is not null and ir.`result` <> ''
and ir.`time` between #{param.period.begin} and #{param.period.end}
and ir.organization_id = #{param.organizationId}
and ir.status = #{param.status}
and ir.`result` = #{param.result}
AND (ir.task_name like concat('%',#{param.keyword},'%') OR ir.target_name like concat('%',#{param.keyword},'%'))
AND DATE_FORMAT(ir.`time`, '%H:%i:%s') BETWEEN #{param.timeStart} AND #{param.timeEnd}
and ir.task_id is not null
and ir.task_id is null
GROUP BY ir.id ORDER BY ir.`time` DESC

SELECT ir.id, ir.target_category, ir.target_id, ir.target_name, if(ir.task_id is null , '临时巡检' , '任务巡检') as inspectMethod, ir.task_id, ir.task_name, ir.status, ir.organization_id, ir.organization_name, ir.user_id, ir.nickname, ir.`time`, ir.`result`, ir.cancel_reason, ir.cancel_file_key, wm_concat(iri.item_name) as errNames, wm_concat(iri.error_desc) as errDesc FROM inspect_record ir LEFT JOIN inspect_record_item iri ON ( iri.record_id = ir.id and iri.error_value_flag = 1) WHERE ir.`result` is not null and ir.`result` <> ''
and ir.`time` between #{param.period.begin} and #{param.period.end}
and ir.organization_id = #{param.organizationId}
and ir.status = #{param.status}
and ir.`result` = #{param.result}
AND ir.task_name like concat('%',#{param.keyword},'%') OR ir.target_name like concat('%',#{param.keyword},'%')
AND TO_CHAR(ir.`time`, 'HH24:MI:SS') BETWEEN #{param.timeStart} AND #{param.timeEnd}
and ir.task_id is not null
and ir.task_id is null
GROUP BY ir.id ORDER BY ir.`time` DESC

SELECT target_id, count(id) as count FROM ( SELECT ir.target_id, ir.id FROM inspect_record ir INNER JOIN inspect_record_item iri ON (ir.id = iri.record_id and iri.error_value_flag = 1)
and ir.`time` > #{param.period.begin} and ir.`time` < #{param.period.end}
and iri.item_tag = #{tag}
and iri.item_tag IS NOT NULL
and ir.target_id in
#{targetId}
GROUP BY ir.id ORDER BY ir.target_id, ir.`time`) t1 GROUP BY target_id

SELECT t2.item_name AS `item`, t1.target_id FROM inspect_record t1 JOIN ( SELECT iri.record_id, iri.item_name, MAX(ir.create_time) AS max_created_at FROM inspect_record ir JOIN inspect_record_item iri ON (iri.record_id = ir.id and iri.error_value_flag = 1)
ir.`time` > #{param.period.begin} and ir.`time` < #{param.period.end}
and iri.item_tag = #{tag}
and iri.item_tag IS NOT NULL
and ir.target_id in
#{targetId}
GROUP BY target_id) t2 ON t1.id = t2.record_id

SELECT ir.id, ir.target_name, ir.`time`, ir.`result`, ir.task_name, ir.nickname, iri.id as error_item_id, GROUP_CONCAT(iri.item_name) as errorItem FROM inspect_record ir LEFT JOIN inspect_record_item iri ON ( iri.record_id = ir.id AND iri.error_value_flag = 1 ) WHERE ir.STATUS = 'OVER' AND ir.`result` IS NOT NULL
and ir.`time` between #{param.period.begin} and #{param.period.end}
and ir.`result` = #{param.result}
GROUP BY ir.id ORDER BY ir.`time` DESC

select sir.id ,sir.`time` ,sir.target_name ,sir.user_id ,sir.nickname ,sir.`result`
,sir.task_id,sir.task_name,GROUP_CONCAT(siri.id) as record_item_id, GROUP_CONCAT(siri.item_name) as errorItem,
count(siri.id) as errNumber
from inspect_record sir
left join inspect_record_item siri on(siri.record_id = sir.id and siri.error_value_flag = 1)


        and sir.`time` >= #{query.period.begin} and `time` < #{query.period.end}


        and sir.target_id = #{query.targetId}


        and task_id is null


        and sir.`result` = #{query.result}


        and sir.target_name = #{query.targetName}


        and siri.item_tag is not null


        and siri.item_tag in

            #{tag}



group by sir.id order by sir.`time` desc

select * from inspect_record

    task_id = #{taskId}

        and target_id in

            #{targetId}

select * from inspect_record


        update_time >= #{period.begin}


        and update_time <= #{period.end}


        and tenant = #{tenant}

SELECT COUNT( ir.id ) FROM `inspect_record` ir WHERE ir.`status` = 'OVER'
and ir.create_time >= #{period.begin}
and ir.create_time <= #{period.end}

SELECT ir.nickname AS name , COUNT( ir.id ) num FROM `inspect_record` ir WHERE ir.`status` = 'OVER'
and ir.create_time >= #{period.begin}
and ir.create_time <= #{period.end}
GROUP BY ir.user_id ORDER BY num
DESC
LIMIT 5

select r.*, t.id as taskId, t.name as taskName, t.status as taskStatus from inspect_record r inner join inspect_task t on (t.id = r.task_id)
r.id in
#{id}

mapper.update:
update inspect_record set status = #{param.status}, update_time = #{updateTime}, update_by = #{updateBy}

    , result = #{param.result}


    , time = #{param.time}


    , user_id = #{param.userId}


    , username = #{param.username}


    , nickname = #{param.nickname}


    , organization_id = #{param.organizationId}


    , organization_name = #{param.organizationName}


    , position_id = #{param.positionId}


    , position_name = #{param.positionName}


    , repair_status = #{param.repairStatus}


    , cancel_reason = #{param.cancelReason}


    , cancel_file_key = #{param.cancelFileKey}


    , cancel_inspect_file_key = #{param.cancelInspectFileKey}


    , cancel_inspect_reason = #{param.cancelInspectReason}


    id in

        #{id}

mapper.select:
select r.id,r.target_id,r.target_category,r.target_name,r.area_name,r.task_id, r.task_name, r.`time`, r.plan_id, r.repair_status, rr.user_id, rr.nickname, r.cancel_file_key, cancel_reason, r.cancel_inspect_file_key, cancel_inspect_reason ,b.id as b_id,b.record_id as order_record_id, b.business_category as order_business_category,b.business_id as order_business_id, b.business_name as order_business_name from inspect_record r inner join inspect_repair_relation rr on (r.id = rr.id) left join inspect_record_to_business b on (r.id = b.record_id)
r.repair_status in ('WAIT_REPAIR','CANCEL_REPAIR','REPAIRED')
and r.id = #{param.recordId}
and r.target_name = #{param.targetName}
and r.repair_status = #{param.repairStatus}
and r.id in
#{recordId}
and r.task_id is null
and r.task_id is not null
order by r.`time` DESC

SELECT ir.* FROM inspect_record ir INNER JOIN ( SELECT ir2.target_id, max(ir2.`time`) `time` FROM inspect_record ir2
AND ir2.target_category = #{param.targetCategory}
AND ir2.target_id = #{param.targetId}
AND ir2.area_id like concat('%',#{param.areaId},'%')
AND ir2.time between #{param.period.begin} and #{param.period.end}
AND ir2.task_name like concat('%',#{param.keyword},'%') OR ir2.target_name like concat('%',#{param.keyword},'%')
AND DATE_FORMAT(ir2.TIME, '%H:%i:%s') BETWEEN #{param.timeStart} AND #{param.timeEnd}
GROUP BY ir2.target_id ) AS ir3 ON (ir.target_id = ir3.target_id AND ir.`time` = ir3.`time`) ORDER BY ir.create_time DESC
